var t=`0157-torta-tre-monti`;var i=`world-0157`;var n=`SM`;var r=`southern-europe`;var o=8;var l=97;var s={en:`Torta Tre Monti`,ua:`Торт Тре Монті`};var h={en:`A home-oven approximation of layered chocolate-hazelnut wafer cake using freshly baked thin crisp sheets, as ready-made wafers are absent from the catalog.`,ua:`Домашній варіант вафельного шоколадно-горіхового торта з тонкими хрусткими коржами власного приготування, оскільки готових вафель у каталозі немає.`};var u=[{en:`Whisk the flour, eggs, sugar, milk and melted butter into a smooth thin wafer batter.`,ua:`Збийте борошно, яйця, цукор, молоко й розтоплене масло в однорідне рідке тісто для вафельних коржів.`,t:[`mixing`,`whisking`],m:10,i:[[`all-purpose-flour`,240,`g`],[`chicken-egg`,3,`pcs`],[`white-granulated-sugar`,100,`g`],[`whole-cow-milk`,250,`ml`],[`unsalted-butter`,70,`g`]]},{en:`Spread into very thin rectangular sheets on lined trays and bake each at 180°C until dry and crisp, about 5–7 minutes per sheet. Cool without stacking.`,ua:`Розподіліть тісто дуже тонкими прямокутними листами на деку з пергаментом і випікайте кожен при 180°C до сухості й хрусткості, орієнтовно 5–7 хвилин. Остуджуйте без складання.`,t:[`baking`],m:28,i:[]},{en:`Melt chocolate with cream, blend in finely ground hazelnuts and cool until spreadable.`,ua:`Розтопіть шоколад із вершками, додайте дрібно мелені горіхи та остудіть до консистенції крему.`,t:[`whipping`],m:7,i:[[`dark-chocolate`,210,`g`],[`heavy-cream`,170,`ml`],[`hazelnut`,130,`g`]]},{en:`Spread thin layers of chocolate-hazelnut cream between crisp homemade wafer sheets; finish with a top coating and press lightly.`,ua:`Промастіть домашні хрусткі коржі тонкими шарами шоколадно-горіхового крему, покрийте верх і злегка притисніть.`,t:[`layered-assembly`,`garnishing`],m:12,i:[]},{en:`Refrigerate only until firm enough to slice; keep finished cake cool and dry to preserve its wafer layers.`,ua:`Охолоджуйте лише до стабілізації перед нарізанням; зберігайте торт у прохолоді та сухості, щоб коржі лишилися хрусткими.`,t:[`rapid-chilling`],m:40,i:[]}];var g={slug:t,id:i,country:`SM`,region:r,servings:8,minutes:97,title:s,text:h,steps:u};export{n as country,g as default,i as id,l as minutes,r as region,o as servings,t as slug,u as steps,h as text,s as title};